// Rain-soaked narrow city street at blue hour — direct 2D painting.
// 1200 x 800. Vanishing region near (600, 350).

function lerp(a, b, t) { return a + (b - a) * t; }
function clamp01(t) { return t < 0 ? 0 : t > 1 ? 1 : t; }

// --- value noise + fbm (seeded through provided rng) ---
const NP = new Float32Array(4096);
(function () {
  for (let i = 0; i < 4096; i++) NP[i] = rng();
})();
function vnoise(x, y) {
  const xi = Math.floor(x), yi = Math.floor(y);
  const xf = x - xi, yf = y - yi;
  const u = xf * xf * (3 - 2 * xf);
  const v = yf * yf * (3 - 2 * yf);
  function h(ix, iy) {
    let n = (ix * 73856093) ^ (iy * 19349663);
    n = n & 4095;
    return NP[n < 0 ? -n : n];
  }
  const a = h(xi, yi), b = h(xi + 1, yi);
  const c = h(xi, yi + 1), d = h(xi + 1, yi + 1);
  return lerp(lerp(a, b, u), lerp(c, d, u), v);
}
function fbm(x, y, oct) {
  let s = 0, a = 0.5, f = 1;
  for (let i = 0; i < oct; i++) {
    s += a * vnoise(x * f, y * f);
    f *= 2.03; a *= 0.5;
  }
  return s;
}

const VX = 600, VY = 350; // vanishing region
const HOR = VY + 30;      // street horizon line

// ---------- geometry helpers ----------
// Map a facade-local coordinate u (0 near camera .. 1 far/vanishing) and vH
// (a height in a local unit) to a screen point along the near/far street edge.
function sideEdgeX(side, u) {
  const nearX = side < 0 ? -140 : W + 140;
  const farX = VX + side * 22;
  const uu = Math.pow(u, 0.82);
  return lerp(nearX, farX, uu);
}
function vpHeightScale(u) {
  return lerp(1, 0.06, Math.pow(u, 0.72));
}
function baseY(u) {
  return lerp(H + 60, HOR + 6, Math.pow(u, 0.68));
}
// returns [x, y, hscale]
function facadePoint(side, u, vH) {
  const x = sideEdgeX(side, u);
  const hs = vpHeightScale(u);
  const y = baseY(u) - vH * hs;
  return [x, y, hs];
}

function quad(x0, y0, x1, y1, x2, y2, x3, y3, fill) {
  ctx.beginPath();
  ctx.moveTo(x0, y0);
  ctx.lineTo(x1, y1);
  ctx.lineTo(x2, y2);
  ctx.lineTo(x3, y3);
  ctx.closePath();
  ctx.fillStyle = fill;
  ctx.fill();
}

// ---------- SKY / ATMOSPHERE ----------
function paintSky() {
  const g = ctx.createLinearGradient(0, 0, 0, HOR + 40);
  g.addColorStop(0, '#1b2b3c');
  g.addColorStop(0.42, '#25405a');
  g.addColorStop(0.75, '#3a5a72');
  g.addColorStop(1, '#5a7286');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, HOR + 60);

  // warm glow just above horizon toward vanishing point
  const rg = ctx.createRadialGradient(VX, HOR - 30, 20, VX, HOR - 30, 460);
  rg.addColorStop(0, 'rgba(150,175,195,0.45)');
  rg.addColorStop(0.5, 'rgba(80,110,135,0.22)');
  rg.addColorStop(1, 'rgba(30,50,70,0)');
  ctx.fillStyle = rg;
  ctx.fillRect(VX - 460, HOR - 490, 920, 520);

  // patchy cloud texture in sky
  ctx.save();
  ctx.globalAlpha = 0.22;
  for (let i = 0; i < 240; i++) {
    const x = rng() * W;
    const y = rng() * (HOR - 80);
    const n = fbm(x * 0.005, y * 0.011, 3);
    if (n < 0.42) continue;
    const r = 22 + n * 70;
    const cl = ctx.createRadialGradient(x, y, 0, x, y, r);
    cl.addColorStop(0, 'rgba(170,195,215,' + (0.10 * n) + ')');
    cl.addColorStop(1, 'rgba(170,195,215,0)');
    ctx.fillStyle = cl;
    ctx.fillRect(x - r, y - r, r * 2, r * 2);
  }
  ctx.restore();
}

// ---------- FACADES ----------
function paintFacades() {
  // LEFT facade base (cool blue-gray)
  const lg = ctx.createLinearGradient(0, 0, VX, 0);
  lg.addColorStop(0, '#33495a');
  lg.addColorStop(0.55, '#2b3e4e');
  lg.addColorStop(0.85, '#37505f');
  lg.addColorStop(1, '#46626f');
  quad(-140, -40, VX - 24, HOR - 240, VX - 24, HOR + 6, -140, H + 60, lg);

  // RIGHT facade base (warm brown-amber)
  const rg = ctx.createLinearGradient(W, 0, VX, 0);
  rg.addColorStop(0, '#4a3a2c');
  rg.addColorStop(0.55, '#3c2f24');
  rg.addColorStop(0.85, '#4a3b2c');
  rg.addColorStop(1, '#5a4836');
  quad(W + 140, -40, VX + 24, HOR - 240, VX + 24, HOR + 6, W + 140, H + 60, rg);

  // wall tone noise patches
  ctx.save();
  for (let i = 0; i < 1400; i++) {
    const side = rng() < 0.5 ? -1 : 1;
    const u = Math.pow(rng(), 1.5) * 0.99;
    const vH = rng() * 340;
    const p = facadePoint(side, u, vH);
    if (p[0] < -30 || p[0] > W + 30) continue;
    const n = fbm(p[0] * 0.018, p[1] * 0.018, 2);
    const r = (1.5 + n * 9) * Math.max(0.4, p[2]);
    const col = side < 0
      ? (n > 0.5 ? '90,130,150' : '25,40,52')
      : (n > 0.5 ? '110,85,60' : '40,30,24');
    ctx.globalAlpha = 0.10 + 0.22 * n;
    ctx.fillStyle = 'rgba(' + col + ',1)';
    ctx.fillRect(p[0] - r, p[1] - r, r * 2, r * 2);
  }
  ctx.restore();

  // subtle horizontal floor bands (medium structure)
  paintFloorBands(-1);
  paintFloorBands(1);

  paintWindows(-1);
  paintWindows(1);
  paintShopfronts(-1);
  paintShopfronts(1);
}

function paintFloorBands(side) {
  ctx.save();
  for (let f = 0; f < 9; f++) {
    const vH = 40 + f * 52;
    const a = facadePoint(side, 0.02, vH);
    const b = facadePoint(side, 0.97, vH);
    ctx.strokeStyle = side < 0 ? 'rgba(140,180,200,0.09)' : 'rgba(190,150,110,0.09)';
    ctx.lineWidth = side < 0 ? 2 : 2;
    ctx.beginPath();
    ctx.moveTo(a[0], a[1]);
    ctx.lineTo(b[0], b[1]);
    ctx.stroke();
  }
  ctx.restore();
}

function paintWindows(side) {
  const cols = 11;
  for (let c = 0; c < cols; c++) {
    const u0 = 0.03 + c * 0.088 + (rng() - 0.5) * 0.012;
    if (u0 > 0.95) continue;
    const u1 = Math.min(0.955, u0 + 0.048 + rng() * 0.012);
    for (let r = 0; r < 8; r++) {
      if (rng() < 0.16) continue;
      const vH0 = 200 + r * 42 + (rng() - 0.5) * 8;
      const wv = 20 + rng() * 8;
      const vH1 = vH0 + wv;
      if (vH1 > 540) continue;

      const p00 = facadePoint(side, u0, vH1);
      const p10 = facadePoint(side, u1, vH1);
      const p11 = facadePoint(side, u1, vH0);
      const p01 = facadePoint(side, u0, vH0);
      if ((p00[0] < -20 && p10[0] < -20) || (p00[0] > W + 20 && p10[0] > W + 20)) continue;

      const depth = p00[2];
      const lit = rng();
      let fill;
      if (side < 0) {
        if (lit < 0.22) fill = 'rgba(175,225,240,' + (0.55 + rng() * 0.3) + ')';
        else if (lit < 0.4) fill = 'rgba(85,130,150,0.7)';
        else fill = 'rgba(22,36,46,0.92)';
      } else {
        if (lit < 0.26) fill = 'rgba(250,195,130,' + (0.55 + rng() * 0.3) + ')';
        else if (lit < 0.44) fill = 'rgba(180,130,85,0.7)';
        else fill = 'rgba(30,24,18,0.92)';
      }
      quad(p00[0], p00[1], p10[0], p10[1], p11[0], p11[1], p01[0], p01[1], fill);

      // window frame hint (thin dark mullion)
      if (depth > 0.15) {
        const mx = (p00[0] + p10[0]) / 2;
        const myT = (p00[1] + p10[1]) / 2;
        const myB = (p01[1] + p11[1]) / 2;
        ctx.strokeStyle = side < 0 ? 'rgba(15,28,38,0.6)' : 'rgba(20,14,10,0.6)';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(mx, myT);
        ctx.lineTo(mx, myB);
        ctx.stroke();
      }

      // interior soft glow for lit windows (small, restrained)
      if ((side < 0 && lit < 0.22) || (side === 1 && lit < 0.26)) {
        const cx = (p00[0] + p10[0] + p11[0] + p01[0]) / 4;
        const cy = (p00[1] + p10[1] + p11[1] + p01[1]) / 4;
        const rad = 22 * depth + 5;
        if (rad > 2) {
          const gg = ctx.createRadialGradient(cx, cy, 0, cx, cy, rad);
          const warm = side === 1;
          gg.addColorStop(0, warm ? 'rgba(255,195,135,0.40)' : 'rgba(175,225,240,0.38)');
          gg.addColorStop(1, warm ? 'rgba(255,195,135,0)' : 'rgba(175,225,240,0)');
          ctx.fillStyle = gg;
          ctx.fillRect(cx - rad, cy - rad, rad * 2, rad * 2);
        }
      }
    }
  }
}

// ---------- SHOPFRONTS + AWNINGS ----------
function paintShopfronts(side) {
  const units = [
    { u0: 0.04, u1: 0.19, warm: side > 0 },
    { u0: 0.22, u1: 0.37, warm: side < 0 },
    { u0: 0.42, u1: 0.56, warm: side > 0 },
    { u0: 0.60, u1: 0.72, warm: side < 0 },
    { u0: 0.76, u1: 0.86, warm: side > 0 }
  ];
  for (const un of units) {
    // shopfront glazing
    const gn = facadePoint(side, un.u1, 8);
    const gf = facadePoint(side, un.u0, 8);
    const gnt = facadePoint(side, un.u1, 92);
    const gft = facadePoint(side, un.u0, 92);
    const litcol = un.warm
      ? 'rgba(250,205,140,' + (0.55 + rng() * 0.2) + ')'
      : 'rgba(150,215,235,' + (0.45 + rng() * 0.2) + ')';
    quad(gnt[0], gnt[1], gf[0], gf[1], gf[0], gf[1], gnt[0], gnt[1], 'rgba(0,0,0,0)');
    quad(gnt[0], gnt[1], gft[0], gft[1], gf[0], gf[1], gn[0], gn[1], litcol);
    // dark mullion verticals in glazing
    const nMul = 4;
    for (let m = 1; m < nMul; m++) {
      const uu = lerp(un.u0, un.u1, m / nMul);
      const a = facadePoint(side, uu, 8);
      const b = facadePoint(side, uu, 92);
      ctx.strokeStyle = 'rgba(20,20,22,0.55)';
      ctx.lineWidth = 1.6;
      ctx.beginPath();
      ctx.moveTo(a[0], a[1]);
      ctx.lineTo(b[0], b[1]);
      ctx.stroke();
    }
    // awning above shopfront
    drawAwning(side, un.u0, un.u1, 100, 128, un.warm);
  }
}

function drawAwning(side, u0, u1, vhTop, vhBot, warm) {
  const a = facadePoint(side, u0, vhTop);
  const b = facadePoint(side, u1, vhTop);
  const c = facadePoint(side, u1, vhBot);
  const d = facadePoint(side, u0, vhBot);
  // push out from wall toward street
  const push = side < 0 ? 26 : -26;
  const pushFar = side < 0 ? 8 : -8;

  const colDark = warm ? 'rgba(86,50,32,0.96)' : 'rgba(34,72,86,0.96)';
  const colEdge = warm ? 'rgba(200,130,80,0.7)' : 'rgba(120,190,210,0.7)';
  const colUnder = warm ? 'rgba(58,32,20,0.95)' : 'rgba(24,50,60,0.95)';

  // top slab
  ctx.beginPath();
  ctx.moveTo(a[0], a[1]);
  ctx.lineTo(b[0], b[1]);
  ctx.lineTo(b[0] + pushFar, b[1] + 14);
  ctx.lineTo(a[0] + push, a[1] + 20);
  ctx.closePath();
  ctx.fillStyle = colDark;
  ctx.fill();

  // under-shadow
  ctx.beginPath();
  ctx.moveTo(a[0] + push, a[1] + 20);
  ctx.lineTo(b[0] + pushFar, b[1] + 14);
  ctx.lineTo(c[0] + pushFar, c[1] + 6);
  ctx.lineTo(d[0] + push, d[1] + 8);
  ctx.closePath();
  ctx.fillStyle = colUnder;
  ctx.fill();

  // scalloped front edge highlight
  ctx.strokeStyle = colEdge;
  ctx.lineWidth = Math.max(1, 2 * (a.length ? 1 : 1));
  ctx.beginPath();
  ctx.moveTo(d[0] + push, d[1] + 8);
  const segs = 5;
  for (let i = 1; i <= segs; i++) {
    const t = i / segs;
    const x = lerp(d[0] + push, c[0] + pushFar, t);
    const y = lerp(d[1] + 8, c[1] + 6, t) + (i % 2 === 0 ? 4 : -1);
    ctx.lineTo(x, y);
  }
  ctx.stroke();
}

// ---------- VERTICAL LUMINOUS SIGNS ----------
function paintSigns() {
  // left cyan signs at multiple depths
  verticalSign(-1, 0.14, 160, 120, 'rgba(140,235,248,1)', 'rgba(60,190,215,0.7)', 20);
  verticalSign(-1, 0.38, 200, 100, 'rgba(120,225,245,0.98)', 'rgba(50,170,200,0.6)', 14);
  verticalSign(-1, 0.66, 240, 70, 'rgba(160,220,240,0.9)', 'rgba(80,170,195,0.5)', 9);
  // right amber/coral signs
  verticalSign(1, 0.12, 150, 130, 'rgba(255,190,130,1)', 'rgba(240,120,70,0.7)', 22);
  verticalSign(1, 0.36, 200, 105, 'rgba(255,175,120,0.98)', 'rgba(235,110,65,0.6)', 15);
  verticalSign(1, 0.64, 240, 72, 'rgba(255,165,115,0.9)', 'rgba(220,100,60,0.5)', 10);
}

function verticalSign(side, u, vhBase, vhH, colBright, colGlow, wBase) {
  const base = facadePoint(side, u, vhBase);
  const top = facadePoint(side, u, vhBase + vhH);
  const depth = base[2];
  const w = Math.max(3, wBase * Math.max(0.25, depth));
  const push = side < 0 ? (18 + 8 * depth) : -(18 + 8 * depth);

  const x0 = base[0] + push;
  const x1 = x0 + (side < 0 ? -w : w);
  const y0 = top[1];
  const y1 = base[1];
  const left = Math.min(x0, x1), right = Math.max(x0, x1);

  // bracket to wall
  ctx.strokeStyle = 'rgba(15,15,18,0.8)';
  ctx.lineWidth = Math.max(1, 2 * depth);
  ctx.beginPath();
  ctx.moveTo(base[0], y0 + 6);
  ctx.lineTo(x0, y0 + 6);
  ctx.moveTo(base[0], y1 - 6);
  ctx.lineTo(x0, y1 - 6);
  ctx.stroke();

  // outer glow halo
  const cx = (left + right) / 2, cy = (y0 + y1) / 2;
  const rad = Math.max(right - left, y1 - y0) * 0.9 + 20;
  const gg = ctx.createRadialGradient(cx, cy, 0, cx, cy, rad);
  gg.addColorStop(0, colGlow);
  gg.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  ctx.globalAlpha = 0.85;
  ctx.fillStyle = gg;
  ctx.fillRect(cx - rad, cy - rad, rad * 2, rad * 2);
  ctx.restore();

  // sign body
  const sg = ctx.createLinearGradient(left, 0, right, 0);
  sg.addColorStop(0, colBright);
  sg.addColorStop(0.6, colBright);
  sg.addColorStop(1, colGlow);
  ctx.fillStyle = sg;
  ctx.fillRect(left, y0, right - left, y1 - y0);

  // bright inner core line
  ctx.fillStyle = 'rgba(255,255,255,' + (0.35 * Math.min(1, depth * 3)) + ')';
  ctx.fillRect(left + (right - left) * 0.35, y0 + 3, (right - left) * 0.3, y1 - y0 - 6);

  // harsh dark segment breaks (no readable glyphs)
  ctx.strokeStyle = 'rgba(10,12,16,0.7)';
  ctx.lineWidth = Math.max(1.2, 2 * depth);
  const segs = Math.max(3, Math.round(vhH / 30));
  for (let i = 1; i < segs; i++) {
    const yy = lerp(y0, y1, i / segs);
    ctx.beginPath();
    ctx.moveTo(left, yy);
    ctx.lineTo(right, yy);
    ctx.stroke();
  }
}

// ---------- CABLES ----------
function paintCables() {
  ctx.save();
  ctx.globalAlpha = 0.45;
  ctx.strokeStyle = 'rgba(10,16,22,0.95)';
  for (let k = 0; k < 4; k++) {
    const yBase = 40 + k * 40;
    ctx.lineWidth = 0.9 + rng() * 1.3;
    ctx.beginPath();
    ctx.moveTo(-10, yBase + 30);
    ctx.bezierCurveTo(W * 0.3, yBase + 55 + rng() * 25, W * 0.62, yBase - 8 + rng() * 25, W + 10, yBase + 25);
    ctx.stroke();
  }
  ctx.restore();
}

// ---------- DISTANT CLUSTER (small, not blobby) ----------
function paintDistant() {
  const dg = ctx.createLinearGradient(0, HOR - 90, 0, HOR + 20);
  dg.addColorStop(0, 'rgba(120,145,165,0.7)');
  dg.addColorStop(1, 'rgba(70,95,115,0.5)');
  ctx.fillStyle = dg;
  ctx.fillRect(VX - 60, HOR - 90, 120, 110);

  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  for (let i = 0; i < 60; i++) {
    const x = VX + (rng() - 0.5) * 90;
    const y = HOR - 30 + (rng() - 0.3) * 60;
    const warm = rng() < 0.5;
    const r = 0.8 + rng() * 1.6;
    const col = warm ? '255,190,130' : '160,220,240';
    const gg = ctx.createRadialGradient(x, y, 0, x, y, r * 4);
    gg.addColorStop(0, 'rgba(' + col + ',0.7)');
    gg.addColorStop(1, 'rgba(' + col + ',0)');
    ctx.fillStyle = gg;
    ctx.fillRect(x - r * 4, y - r * 4, r * 8, r * 8);
  }
  ctx.restore();
}

// ---------- WET PAVEMENT ----------
function paintPavement() {
  const rg = ctx.createLinearGradient(0, HOR, 0, H);
  rg.addColorStop(0, '#5a6a78');
  rg.addColorStop(0.25, '#3e4c58');
  rg.addColorStop(0.65, '#28323c');
  rg.addColorStop(1, '#161d24');
  ctx.fillStyle = rg;
  ctx.fillRect(0, HOR, W, H - HOR);

  // fog haze near horizon
  const fg = ctx.createLinearGradient(0, HOR, 0, HOR + 100);
  fg.addColorStop(0, 'rgba(120,145,165,0.55)');
  fg.addColorStop(1, 'rgba(120,145,165,0)');
  ctx.fillStyle = fg;
  ctx.fillRect(0, HOR, W, 100);

  // ---- coherent broken road reflections ----
  // reflection columns of the vertical signs & lit windows
  const refls = [
    { x: VX - 300, w: 90, col: '140,225,245', int: 0.32 },
    { x: VX - 180, w: 70, col: '120,210,235', int: 0.26 },
    { x: VX - 70, w: 45, col: '150,225,245', int: 0.22 },
    { x: VX + 90, w: 55, col: '255,185,120', int: 0.28 },
    { x: VX + 200, w: 85, col: '255,170,110', int: 0.32 },
    { x: VX + 340, w: 100, col: '255,160,100', int: 0.30 }
  ];

  const bandsN = 160;
  for (let b = 0; b < bandsN; b++) {
    const t = b / bandsN;
    const y = lerp(HOR + 3, H + 10, Math.pow(t, 0.55));
    const spread = lerp(15, W * 0.9, Math.pow(t, 1.15));

    for (const ref of refls) {
      // spread of reflection column as we approach camera
      const spreadFactor = lerp(0.35, 1.5, t);
      const rcx = VX + (ref.x - VX) * lerp(0.7, 1.4, t);
      const halfW = ref.w * spreadFactor * 0.5;
      const segs = 2 + Math.floor(t * 5);
      for (let s = 0; s < segs; s++) {
        const sx = rcx + (rng() - 0.5) * halfW * 1.6;
        const sw = lerp(6, 26, t) * (0.4 + rng() * 1.1);
        const sh = lerp(1.2, 6, t) * (0.6 + rng() * 0.8);
        const bright = ref.int * (0.4 + 0.7 * (1 - Math.abs(sx - VX) / spread));
        if (bright < 0.04) continue;
        // broken: skip randomly
        if (rng() < 0.28) continue;
        ctx.fillStyle = 'rgba(' + ref.col + ',' + bright + ')';
        ctx.fillRect(sx - sw / 2, y - sh / 2, sw, sh);
      }
    }

    // occasional neutral sheen streaks crossing center
    if (t > 0.2 && rng() < 0.8) {
      const sx = VX + (rng() - 0.5) * spread * 1.2;
      const sw = lerp(10, 70, t) * (0.3 + rng() * 0.9);
      const sh = lerp(1, 4, t) * (0.5 + rng() * 0.6);
      ctx.fillStyle = 'rgba(150,180,200,' + (0.08 + rng() * 0.12) + ')';
      ctx.fillRect(sx - sw / 2, y - sh / 2, sw, sh);
    }

    // dark puddle gaps
    if (t > 0.18 && rng() < 0.55) {
      const gx = VX + (rng() - 0.5) * spread * 1.6;
      const gw = lerp(20, 150, t) * rng();
      const gh = lerp(2, 10, t);
      ctx.fillStyle = 'rgba(18,26,34,' + (0.35 + rng() * 0.35) + ')';
      ctx.fillRect(gx - gw / 2, y - gh / 2, gw, gh);
    }
  }

  // foreground vignette darkening of street
  const vg = ctx.createRadialGradient(VX, HOR + 80, 40, VX, HOR + 80, 640);
  vg.addColorStop(0, 'rgba(20,30,40,0.05)');
  vg.addColorStop(0.6, 'rgba(12,18,24,0.18)');
  vg.addColorStop(1, 'rgba(0,0,0,0.45)');
  ctx.fillStyle = vg;
  ctx.fillRect(0, HOR, W, H - HOR);

  // faint center lane line
  ctx.strokeStyle = 'rgba(160,170,180,0.12)';
  ctx.lineWidth = 3;
  ctx.setLineDash([12, 18]);
  ctx.beginPath();
  ctx.moveTo(VX, HOR + 5);
  ctx.lineTo(VX, H + 10);
  ctx.stroke();
  ctx.setLineDash([]);
}

// ---------- CURBS / SIDEWALKS ----------
function paintCurbs() {
  // left curb band
  ctx.beginPath();
  ctx.moveTo(-20, H + 10);
  ctx.lineTo(VX - 22, HOR + 6);
  ctx.lineTo(VX - 6, HOR + 6);
  ctx.lineTo(-20, H + 10);
  ctx.closePath();
  ctx.fillStyle = 'rgba(60,78,92,0.6)';
  ctx.fill();

  ctx.beginPath();
  ctx.moveTo(W + 20, H + 10);
  ctx.lineTo(VX + 22, HOR + 6);
  ctx.lineTo(VX + 6, HOR + 6);
  ctx.lineTo(W + 20, H + 10);
  ctx.closePath();
  ctx.fillStyle = 'rgba(78,64,50,0.6)';
  ctx.fill();

  const cg = ctx.createLinearGradient(0, HOR, 0, H);
  cg.addColorStop(0, 'rgba(110,140,160,0.35)');
  cg.addColorStop(1, 'rgba(40,52,62,0.2)');
  ctx.strokeStyle = cg;
  ctx.lineWidth = 2.5;
  ctx.beginPath();
  ctx.moveTo(-20, H);
  ctx.lineTo(VX - 22, HOR + 6);
  ctx.stroke();
  ctx.strokeStyle = 'rgba(170,140,105,0.35)';
  ctx.beginPath();
  ctx.moveTo(W + 20, H);
  ctx.lineTo(VX + 22, HOR + 6);
  ctx.stroke();
}

// ---------- UMBRELLA FIGURES ----------
function umbrella(x, y, scale, warm) {
  const w = 24 * scale;
  const h = 13 * scale;
  const bodyH = 38 * scale;
  ctx.save();
  // legs
  ctx.fillStyle = 'rgba(10,14,20,0.95)';
  ctx.fillRect(x - 4 * scale, y - 14 * scale, 3 * scale, 16 * scale);
  ctx.fillRect(x + 1 * scale, y - 14 * scale, 3 * scale, 16 * scale);
  // body coat
  ctx.fillStyle = 'rgba(14,18,24,0.96)';
  ctx.beginPath();
  ctx.moveTo(x - 6 * scale, y - 12 * scale);
  ctx.lineTo(x - 5 * scale, y - bodyH);
  ctx.lineTo(x + 5 * scale, y - bodyH);
  ctx.lineTo(x + 6 * scale, y - 12 * scale);
  ctx.closePath();
  ctx.fill();
  // head
  ctx.beginPath();
  ctx.arc(x, y - bodyH - 2 * scale, 3.5 * scale, 0, Math.PI * 2);
  ctx.fillStyle = 'rgba(16,20,26,0.96)';
  ctx.fill();
  // umbrella canopy
  const cy = y - bodyH - 8 * scale;
  ctx.beginPath();
  ctx.moveTo(x - w, cy + h * 0.35);
  ctx.quadraticCurveTo(x - w * 0.5, cy - h, x, cy - h);
  ctx.quadraticCurveTo(x + w * 0.5, cy - h, x + w, cy + h * 0.35);
  ctx.quadraticCurveTo(x + w * 0.4, cy + h * 0.65, x, cy + h * 0.55);
  ctx.quadraticCurveTo(x - w * 0.4, cy + h * 0.65, x - w, cy + h * 0.35);
  ctx.closePath();
  ctx.fillStyle = 'rgba(9,12,18,0.98)';
  ctx.fill();
  // rim light
  ctx.strokeStyle = warm ? 'rgba(255,180,120,0.7)' : 'rgba(150,220,240,0.65)';
  ctx.lineWidth = Math.max(1, 1.3 * scale);
  ctx.beginPath();
  ctx.moveTo(x - w, cy + h * 0.35);
  ctx.quadraticCurveTo(x - w * 0.5, cy - h, x, cy - h);
  ctx.quadraticCurveTo(x + w * 0.5, cy - h, x + w, cy + h * 0.35);
  ctx.stroke();
  // pole
  ctx.strokeStyle = 'rgba(18,22,28,0.9)';
  ctx.lineWidth = Math.max(1, 1.2 * scale);
  ctx.beginPath();
  ctx.moveTo(x, cy + h * 0.55);
  ctx.lineTo(x, cy + h * 0.55 + 20 * scale);
  ctx.stroke();
  ctx.restore();
}

function paintFigures() {
  umbrella(VX - 150, HOR + 175, 1.1, false);
  umbrella(VX + 130, HOR + 195, 1.3, true);
  umbrella(VX - 40, HOR + 145, 0.8, true);
  umbrella(VX + 55, HOR + 130, 0.7, false);
}

// ---------- LAMP POSTS + GLOWS ----------
function lampPost(side, u, warm) {
  const p = facadePoint(side, u, 0);
  const top = facadePoint(side, u, 200);
  const depth = p[2];
  const x = p[0] + (side < 0 ? 34 * Math.max(0.3, depth) : -34 * Math.max(0.3, depth));
  const yBase = p[1];
  const yTop = top[1] + 40;

  // bracket arm from wall
  ctx.strokeStyle = 'rgba(20,24,30,0.9)';
  ctx.lineWidth = Math.max(1, 3 * depth);
  ctx.beginPath();
  ctx.moveTo(p[0], yTop);
  ctx.lineTo(x, yTop);
  ctx.stroke();

  // lamp head
  const lx = x, ly = yTop + 6;
  const lr = 4 + 4 * Math.max(0.3, depth);
  ctx.fillStyle = warm ? 'rgba(255,210,150,1)' : 'rgba(200,240,250,1)';
  ctx.beginPath();
  ctx.ellipse(lx, ly, lr * 1.4, lr, 0, 0, Math.PI * 2);
  ctx.fill();

  // glow
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  const rad = 70 * Math.max(0.35, depth) + 25;
  const gg = ctx.createRadialGradient(lx, ly, 0, lx, ly, rad);
  gg.addColorStop(0, warm ? 'rgba(255,190,120,0.5)' : 'rgba(170,225,240,0.45)');
  gg.addColorStop(0.4, warm ? 'rgba(255,170,100,0.18)' : 'rgba(150,210,230,0.16)');
  gg.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = gg;
  ctx.fillRect(lx - rad, ly - rad, rad * 2, rad * 2);
  ctx.restore();
}

function paintLamps() {
  lampPost(-1, 0.09, false);
  lampPost(-1, 0.34, false);
  lampPost(-1, 0.62, false);
  lampPost(1, 0.11, true);
  lampPost(1, 0.37, true);
  lampPost(1, 0.65, true);
}

// ---------- RAIN ----------
function paintRain() {
  ctx.save();
  ctx.lineCap = 'round';
  for (let i = 0; i < 760; i++) {
    const x = rng() * W;
    const y = rng() * H;
    const near = y > HOR + 120;
    if (near && rng() < 0.4) continue;
    const n = fbm(x * 0.009, y * 0.009, 2);
    if (n < 0.38) continue;
    const len = (near ? 12 : 8) + rng() * (near ? 18 : 12);
    const dx = -len * 0.28;
    const dy = len;
    const bright = 0.08 + rng() * 0.24;
    const warm = x > VX ? 1 : 0;
    const col = warm
      ? 'rgba(240,195,165,' + bright + ')'
      : 'rgba(180,220,235,' + bright + ')';
    ctx.strokeStyle = col;
    ctx.lineWidth = 0.6 + rng() * 0.9;
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x + dx, y + dy);
    ctx.stroke();
  }
  // brighter foreground slanted streaks
  for (let i = 0; i < 60; i++) {
    const x = rng() * W;
    const y = HOR + 120 + rng() * (H - HOR - 120);
    const len = 24 + rng() * 34;
    ctx.strokeStyle = 'rgba(200,225,240,' + (0.09 + rng() * 0.13) + ')';
    ctx.lineWidth = 1 + rng() * 0.8;
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x - len * 0.28, y + len);
    ctx.stroke();
  }
  ctx.restore();
}

// ---------- FINAL VIGNETTE + GRADE ----------
function paintVignette() {
  const vg = ctx.createRadialGradient(W * 0.5, H * 0.46, H * 0.32, W * 0.5, H * 0.46, H * 0.85);
  vg.addColorStop(0, 'rgba(0,0,0,0)');
  vg.addColorStop(1, 'rgba(4,8,12,0.52)');
  ctx.fillStyle = vg;
  ctx.fillRect(0, 0, W, H);

  ctx.fillStyle = 'rgba(24,44,64,0.08)';
  ctx.fillRect(0, 0, W, HOR);
}

